%[text] # LMI Examples with PhasorArray Toolbox
%[text] This script demonstrates how to build and solve LMIs using the `PhasorArray` toolbox. 
%[text] It is designed as a modern reference template, superseding older scripts.
%[text] For domain-specific applications (like Motor Control), see the `templates/SPMSM-Example` folder.

%% 1. Autonomous System Definition
%[text] Let's define an autonomous periodic system:
%[text] $$ \\dot{x}(t) = A(t) x(t) $$
%[text] We generate a random $A(t)$ with a Hurwitz structure (prescribed stable Floquet exponents) and 5 harmonics.
h = 15;
nx = 6;
T = 1; % period
poles = (-1:-1:-nx)/10 - 2;
A = PhasorArray.randomWithNPole(poles(:), 5, "Method", "generic", "amp", 2);
A = mreal(A); % extract real part

N_mat = N_tb(nx, h, T); % Harmonic derivative matrix

figure(10); clf; %[output:250e9160]
stem(A); %[output:250e9160]
sgtitle('Harmonic Spectrum of A(t)'); %[output:250e9160]

figure(11); clf; %[output:614ef4e4]
plot(A, T, 0:0.01:2); %[output:614ef4e4]
sgtitle('Time-domain A(t)'); %[output:614ef4e4]

figure(12); clf; %[output:832dc1b8]
plot(A.HmqNEig(40,T),'*'); %[output:832dc1b8]
sgtitle('Harmonic Spectrum of A(t)'); %[output:832dc1b8]


%%
%% 2. Stability Analysis
%[text] ## Quadratic Stability Analysis
%[text] To prove the stability of $\\dot{x}(t) = A(t)x(t)$, we search for a real, symmetric, positive-definite periodic Lyapunov matrix $P(t) \> 0$ such that:
%[text] $$ A(t)^T P(t) + P(t) A(t) - \\dot{P}(t) \\leq -\\epsilon I $$
%[text] In the frequency domain, applying the block Toeplitz operator $\\mathcal{T}(\\cdot)$, this LMI becomes:
%[text] $$ \\mathcal{T}(A^T P + P A) - (N \\mathcal{T}(P) - \\mathcal{T}(P) N) \\leq -\\epsilon I $$

h_lmi = 10;
P = PhasorArray.ndsdpvar(nx, nx, h_lmi, 'PhasorType', 'symmetric', 'real', true);

% 1. Form the time-domain products (convolutions in frequency)
ATPpPA = (A.')*P + P*A;

% 2. Extract the Toeplitz block matrix
PT = P.T_tb(h_lmi);
ATPpPA_T = ATPpPA.T_tb(h_lmi);
N_lmi = N_tb(nx, h_lmi, T);

% 3. Formulate the LMI
Pdot_T = N_lmi * PT - PT * N_lmi;
F = [PT >= 1e-6 * eye(size(PT))];
G1 = ATPpPA_T - Pdot_T;
F = [F, G1 <= -10 * eye(size(G1))];

% 4. Solve
disp('Solving Stability LMI...'); %[output:26327990]
sol = optimize(F, [], sdpsettings('solver', 'mosek', 'verbose', 0));
if sol.problem ~= 0 %[output:group:06cc19bb]
    warning('Stability LMI infeasible: %s', sol.info);
else
    disp('Stability LMI Solved Successfully!'); %[output:8274a0e3]
    P_val = sdpval(P);
    figure(21); clf; %[output:08579b86]
    plot(P_val); %[output:08579b86]
    sgtitle('Lyapunov Matrix P(t)'); %[output:08579b86]
end %[output:group:06cc19bb]

%% 3. State-Feedback Synthesis
%[text] ## Periodic State-Feedback (Stabilization)
%[text] Consider the controlled system:
%[text] $$ \\dot{x}(t) = A(t)x(t) + B(t)u(t) $$
%[text] We seek a state-feedback control law $u(t) = K(t)x(t)$ that stabilizes the system. Using the variable change $Y(t) = K(t)Q(t)$ and $Q(t) = P(t)^{-1}$, the LMI condition is:
%[text] $$ A(t)Q(t) + Q(t)A(t)^T - \\dot{Q}(t) + B(t)Y(t) + Y(t)^T B(t)^T \\leq -2\\alpha Q(t) $$

nu = 2;
hb = 3;
B = mreal(PhasorArray(rand_phasor(nx, nu, hb)));

Q = PhasorArray.ndsdpvar(nx, nx, h_lmi, 'PhasorType', 'symmetric', 'real', true);
Y = PhasorArray.ndsdpvar(nu, nx, h_lmi, 'PhasorType', 'full', 'real', true);

% 1. Time-domain products
QA_AQ = Q*(A.') + A*Q;

% 2. Toeplitz equivalents
QT = Q.T_tb(h_lmi);
QA_AQ_T = QA_AQ.T_tb(h_lmi);
BT = B.T_tb(h_lmi);
YT = Y.T_tb(h_lmi);
Qdot_T = N_lmi * QT - QT * N_lmi;

% 3. Formulate the LMI
alpha_decay = 4; % Desired decay rate
F_syn = [QT >= 1e-6 * eye(size(QT))];
% Bound Q to prevent the objective from scaling to infinity
F_syn = [F_syn, QT <= 1e4 * eye(size(QT))]; 

G2 = QA_AQ_T - Qdot_T + BT*YT + YT'*BT';
F_syn = [F_syn, G2 <= -2 * alpha_decay * QT];

% Objective: Minimize Q to limit the magnitude of the Lyapunov function
obj = trace(Q.phas(0)); 

disp('Solving Synthesis LMI...'); %[output:40ae50fc]
sol_syn = optimize(F_syn, obj, sdpsettings('solver', 'mosek', 'verbose', 0));
if sol_syn.problem ~= 0 %[output:group:1cd6a627]
    warning('Synthesis LMI infeasible: %s', sol_syn.info);
else
    disp('Synthesis LMI Solved Successfully!'); %[output:395ff913]
    % 4. Recover Gain K(t)
    K = sdpval(Y) / sdpval(Q);
    K = K.reduce('reduceMethod', 'relative', 'reduceThreshold', 1e-4);
    
    figure(31); clf; %[output:41c3e663]
    plot(K); %[output:41c3e663]
    sgtitle('Optimal Periodic Gain K(t)'); %[output:41c3e663]
end %[output:group:1cd6a627]

